// EZ Drive — implementation. See ezdrive.h and ezfx.h.
//
// 2x oversampling keeps the harmonics generated by the saturator from folding
// back into the audible band. The tone control is a low/high tilt around
// 900 Hz; a one-pole high-pass after the shaper removes DC and the bias offset.
#include "ezdrive.h"

#include "ezfx.h"

#include <juce_dsp/juce_dsp.h>

#include <algorithm>
#include <array>
#include <cmath>
#include <memory>

namespace ezdrive {
namespace {

struct OnePole
{
    inline float lowpass(float input, float a)
    {
        z += a * (input - z);
        return z;
    }

    inline float highpass(float input, float a)
    {
        return input - lowpass(input, a);
    }

    void reset() { z = 0.0f; }

    float z = 0.0f;
};

class EzDriveProcessor final : public ezfx::Effect
{
public:
    EzDriveProcessor()
        : Effect("EZ Drive", "EZDrive")
    {
        drive_ = addFloat("drv", "Drive", 0.0f, 36.0f, 12.0f, "dB");
        tone_ = addFloat("ton", "Tone", -100.0f, 100.0f, 0.0f, "%");
        bias_ = addFloat("bia", "Bias", -50.0f, 50.0f, 0.0f, "%");
        mode_ = addChoice("mode", "Mode",
                          {"Soft", "Hard", "Tube", "Fold"}, 0);
        lowCut_ = addFloat("lcf", "Low cut", 20.0f, 500.0f, 30.0f, "Hz", 100.0f);
        mix_ = addFloat("mix", "Mix", 0.0f, 100.0f, 100.0f, "%");
        output_ = addFloat("out", "Output", -24.0f, 12.0f, -3.0f, "dB");
        bypass_ = addBool("byp", "Bypass", false);
    }

    void prepareDsp(double sampleRate, int maximumBlockSize) override
    {
        sampleRate_ = sampleRate;
        oversampling_ = std::make_unique<juce::dsp::Oversampling<float>>(
            2, 1, juce::dsp::Oversampling<float>::filterHalfBandPolyphaseIIR,
            true, false);
        oversampling_->initProcessing((size_t) maximumBlockSize);
        oversampling_->reset();
        for (auto& s : toneState_)
            s.reset();
        for (auto& s : lowCutState_)
            s.reset();
        driveDb_ = drive_->get();
        toneAmount_ = juce::jlimit(-1.0f, 1.0f, tone_->get() / 100.0f);
        biasAmount_ = juce::jlimit(-0.5f, 0.5f, bias_->get() / 100.0f * 0.5f);
        mixState_ = juce::jlimit(0.0f, 1.0f, mix_->get() / 100.0f);
        outputDb_ = output_->get();
    }

    void releaseDsp() override { oversampling_.reset(); }

    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override
    {
        juce::ScopedNoDenormals noDenormals;
        const int n = buffer.getNumSamples();
        if (n <= 0 || buffer.getNumChannels() < 2 || bypass_->get()
            || oversampling_ == nullptr)
            return;

        const float driveTarget = drive_->get();
        const float toneTarget = juce::jlimit(-1.0f, 1.0f, tone_->get() / 100.0f);
        const float biasTarget =
            juce::jlimit(-0.5f, 0.5f, bias_->get() / 100.0f * 0.5f);
        const float mixTarget = juce::jlimit(0.0f, 1.0f, mix_->get() / 100.0f);
        const float outTarget = output_->get();
        const int mode = mode_->getIndex();
        const float oversampledRate = (float) sampleRate_ * 2.0f;
        const float toneCoeff = ezfx::Effect::coeffFor(900.0f, oversampledRate);
        const float lowCutCoeff =
            ezfx::Effect::coeffFor(lowCut_->get(), oversampledRate);
        const float smooth = 0.0015f;

        auto block = juce::dsp::AudioBlock<float>(buffer)
                         .getSubsetChannelBlock(0, 2);
        auto up = oversampling_->processSamplesUp(block);
        const int upN = (int) up.getNumSamples();
        for (int i = 0; i < upN; ++i)
        {
            driveDb_ += smooth * (driveTarget - driveDb_);
            toneAmount_ += smooth * (toneTarget - toneAmount_);
            biasAmount_ += smooth * (biasTarget - biasAmount_);
            mixState_ += smooth * (mixTarget - mixState_);
            outputDb_ += smooth * (outTarget - outputDb_);

            const float driveGain = juce::Decibels::decibelsToGain(driveDb_);
            const float driveComp =
                1.0f / std::sqrt(juce::jmax(1.0f, driveGain));
            const float dryL = up.getSample(0, i);
            const float dryR = up.getSample(1, i);
            float wetL = dryL * driveGain + biasAmount_;
            float wetR = dryR * driveGain + biasAmount_;

            switch (mode)
            {
                case 1: // Hard
                    wetL = juce::jlimit(-1.0f, 1.0f, wetL);
                    wetR = juce::jlimit(-1.0f, 1.0f, wetR);
                    break;
                case 2: // Tube (asymmetric)
                    wetL = wetL >= 0.0f ? std::tanh(wetL)
                                        : std::tanh(wetL * 0.62f) * 0.82f;
                    wetR = wetR >= 0.0f ? std::tanh(wetR)
                                        : std::tanh(wetR * 0.62f) * 0.82f;
                    break;
                case 3: // Fold
                    wetL = std::sin(wetL);
                    wetR = std::sin(wetR);
                    break;
                default: // Soft
                    wetL = std::tanh(wetL);
                    wetR = std::tanh(wetR);
                    break;
            }
            wetL *= driveComp;
            wetR *= driveComp;

            // Tilt EQ: low and high bands weighted in opposite directions.
            const float lowL = toneState_[0].lowpass(wetL, toneCoeff);
            const float lowR = toneState_[1].lowpass(wetR, toneCoeff);
            const float highL = wetL - lowL;
            const float highR = wetR - lowR;
            wetL = lowL * (1.0f - 0.75f * toneAmount_)
                 + highL * (1.0f + 0.75f * toneAmount_);
            wetR = lowR * (1.0f - 0.75f * toneAmount_)
                 + highR * (1.0f + 0.75f * toneAmount_);

            wetL = lowCutState_[0].highpass(wetL, lowCutCoeff);
            wetR = lowCutState_[1].highpass(wetR, lowCutCoeff);

            const float gain = juce::Decibels::decibelsToGain(outputDb_);
            up.setSample(
                0, i, (dryL + (wetL - dryL) * mixState_) * gain);
            up.setSample(
                1, i, (dryR + (wetR - dryR) * mixState_) * gain);
        }
        oversampling_->processSamplesDown(block);
    }

private:
    juce::AudioParameterFloat* drive_ = nullptr;
    juce::AudioParameterFloat* tone_ = nullptr;
    juce::AudioParameterFloat* bias_ = nullptr;
    juce::AudioParameterChoice* mode_ = nullptr;
    juce::AudioParameterFloat* lowCut_ = nullptr;
    juce::AudioParameterFloat* mix_ = nullptr;
    juce::AudioParameterFloat* output_ = nullptr;
    juce::AudioParameterBool* bypass_ = nullptr;

    std::unique_ptr<juce::dsp::Oversampling<float>> oversampling_;
    std::array<OnePole, 2> toneState_ {};
    std::array<OnePole, 2> lowCutState_ {};
    float driveDb_ = 12.0f;
    float toneAmount_ = 0.0f;
    float biasAmount_ = 0.0f;
    float mixState_ = 1.0f;
    float outputDb_ = -3.0f;
};

} // namespace

juce::AudioProcessor* create()
{
    return new EzDriveProcessor();
}

} // namespace ezdrive
